// Which upload to check. The Werkbank shows the upload ID after "Send rows to n8n…".
const b = $input.first().json.body ?? $input.first().json;
const valid = (d) => typeof d === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(d) && !Number.isNaN(Date.parse(d));
const errors = [];
if (typeof b.batchId !== 'string' || !/^[A-Za-z0-9._-]{1,80}$/.test(b.batchId)) errors.push('batchId (the upload ID) is required');
// Without asOf the reference date is fixed (19 Oct 2026), so the demo file gives the same result every day.
const asOf = valid(b.asOf) ? b.asOf : '2026-10-19';
const withinDays = Number.isFinite(b.withinDays) ? Math.max(1, Math.min(365, Math.round(b.withinDays))) : 30;
return [{ json: { ok: errors.length === 0, errors, batchId: b.batchId, asOf, withinDays } }];

// Reads the rows of the upload (columns as in examples/demo-data/contracts-demo.xlsx) and checks every notice deadline.
// Ends in "draft only": nothing is sent, the owner decides about notice or renewal.
const p = $('Parameters').first().json;
const num = (v) => Number(String(v ?? '').replace(/\s/g, '').replace(',', '.'));
const day = (v) => {
  const s = String(v ?? '').trim();
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
  // Excel stores dates as day numbers (1900 system). 25569 = 1970-01-01.
  if (/^\d{5}(\.\d+)?$/.test(s)) return new Date((Math.floor(Number(s)) - 25569) * 864e5).toISOString().slice(0, 10);
  return '';
};
const rows = $input.all().map((i) => i.json).filter((r) => r && r.data);
const skipped = [];
const contracts = [];
for (const r of rows) {
  const d = r.data;
  const end = day(d['Contract end']);
  const noticeDays = num(d['Notice days']);
  if (!d['Contract ID'] || !end || !Number.isFinite(noticeDays)) { skipped.push(r.row_index); continue; }
  const deadline = new Date(Date.parse(end) - noticeDays * 864e5).toISOString().slice(0, 10);
  const daysLeft = Math.round((Date.parse(deadline) - Date.parse(p.asOf)) / 864e5);
  contracts.push({
    id: d['Contract ID'], customer: d['Customer'] ?? '', product: d['Product'] ?? '', owner: d['Owner'] ?? '', end, noticeDays,
    value: Number.isFinite(num(d['Annual value EUR'])) ? num(d['Annual value EUR']) : 0, noticeDeadline: deadline, daysLeft,
    status: daysLeft <= p.withinDays ? 'alert' : 'ok',
  });
}
contracts.sort((a, b) => a.daysLeft - b.daysLeft);
const alerts = contracts.filter((c) => c.status === 'alert');
const passed = alerts.filter((c) => c.daysLeft < 0);
const byOwner = {};
for (const a of alerts) (byOwner[a.owner || 'unassigned'] ??= []).push(a.id);
const eur = (n) => new Intl.NumberFormat('en-US').format(Math.round(n));
const lines = [
  `Contract notice check for upload ${p.batchId} as of ${p.asOf}: ${contracts.length} contracts, ${alerts.length} with a notice deadline within ${p.withinDays} days or already passed (${passed.length} passed), EUR ${eur(alerts.reduce((s, a) => s + a.value, 0))} annual value affected.`,
  ...alerts.map((a) => `- ${a.id} ${a.customer}, ${a.product}: deadline ${a.noticeDeadline} (${a.daysLeft < 0 ? `${-a.daysLeft} days ago` : `in ${a.daysLeft} days`}), owner ${a.owner}`),
  skipped.length ? `${skipped.length} rows were skipped (missing contract ID, end date or notice days).` : '',
  alerts.length ? 'Draft only: nothing is sent. The owner decides about notice or renewal.' : 'Nothing to do now.',
].filter(Boolean);
return [{ json: { batchId: p.batchId, asOf: p.asOf, withinDays: p.withinDays, total: contracts.length, alerts: alerts.length, passed: passed.length, skipped: skipped.length, byOwner, alertContracts: alerts, digest: lines.join('\n') } }];
